function range(n, h, s, v, overscan = 2) {
  if (n === 0) return [0, 0];
  const top = Math.min(Math.max(0, s), Math.max(0, n * h - v));
  return [
    Math.max(0, Math.floor(top / h) - overscan),
    Math.min(n, Math.ceil((top + v) / h) + overscan)
  ];
}

